import json
from catalog_source_integrity import verify_source
from fastp_workflow_validation import verify,sha

def fastp_metadata(root,data):
    summary=verify(root,data,emit=False);proof=json.loads((root/'docs/literature/FASTP_WORKFLOW_DEVELOPMENT_VALIDATION.json').read_bytes());roles=json.loads((data/'fastp-role-coverage.json').read_bytes())
    assert roles['status']=='passed-seven-fastp-primary-source-role-reviews' and roles['applied'] and roles['reviewed_roles']==7 and roles['unrelated_prior_reviews_preserved']==760 and roles['total_reviews']==767
    verify_source(root,data,'tools/literature/reviewed-uses.json',roles['reviews_sha256'])
    for name,field in [('tools/literature/curate_fastp_uses.py','curator_sha256'),('tools/literature/fastp-use-reviews.json','draft_sha256')]:assert sha((root/name).read_bytes())==roles[field]
    return dict(implementation_status='upstream-adapter-validated',implementation_source='src/main/java/org/jlinalg/cli/FastpToolsCli.java',
        coverage_note='Seven source-reviewed fastp roles preserve the full250-paper/2430-observation cohort and all760 unrelated prior reviews. One prior default-processing description is clarified and six role summaries are added.',
        implementation_scope='Typed current-source fastp-tools runs exact original0.22.0/0.23.2/0.25.0/1.0.1 on Linux x86_64. Complete captured plain/gzip single/paired FASTQ with explicit encoding,alphabet,plus and pair policies;typed adapters,global/quality cuts,filters,poly-G/X,correction,deduplication and orphans. Java recomputes all source summary/cycle/five-mer statistics and complete conservation/transformation envelopes. Portable verification replays every audit/index/disposition with copied setup evidence,without accessing producer inputs/runtime. Adapter,overlap,poly-tail and Bloom choices are retained upstream,not independently reimplemented. No UMI,merge,split,streaming,index-filter or adapter-FASTA-list contract. P089 patch and P110/P223 editions remain unresolved;P054 barcodes and full paper settings are not inferred. Older released0.3.7 JARs lack this CLI;read FASTP_WORKFLOW.md.',
        validation_note=f"58 fresh public original workflows:57 small controls across four editions plus an84,300,000-byte/300,000-read input. All{summary['input_reads']} input reads are accounted for;{summary['represented_reads']} represented and{summary['unrepresented_reads']} unrepresented. Java independently recomputes{summary['independently_recomputed_report_fields']} report values and additionally constrains{summary['additionally_constrained_report_fields']} fields. The exact P054 accuracy6 synthetic option configuration completed with about24.05GiB sampledRSS;barcode/full biological reproduction remains open. All415 actual-JAR checks pass on Linux Java21;Windows Java21/25 each pass398 and explicitly abort17 Linux-only controls,with128MiB heaps. The large bundle also verifies on Windows with128MiB. Exported exact offline setup,user analysis and portable verification plus the emitted beginner recipe are tested. Initial launch-state finalization/test compilation failures remain retained without promotion. Small synthetic data and a large repeated-sequence I/O regression do not certify biological accuracy.",
        project_adapter_available=True,canonical_adapter_available=False,native_helper_available=True,development_adapter_cli='fastp-tools',development_candidate=proof['packaged_candidate'],development_candidate_sha256=proof['packaged_candidate_sha256'],
        source_roles_reviewed=7,workflow_validation='../FASTP_WORKFLOW_DEVELOPMENT_VALIDATION.json',source_role_coverage='fastp-role-coverage.json',runtime_profiles=proof['profiles'],external_analysis_runtime_required=True,whole_paper_reproduced=False,biological_accuracy_certified=False,paper_exact_unknown_settings_available=False)

